std::vector<std::string> collectActiveUsers(const std::vector<User>& users, Instant cutoff) {
    std::vector<std::string> activeUsers;

    for (const auto& user : users) {
        if (!user.isOnline() || user.lastSeenAt() <= cutoff) {
            continue;
        }

        activeUsers.push_back(user.name());
    }

    return activeUsers;
}

std::unordered_map<std::string, std::vector<std::string>> groupPostsByTag(const std::vector<Post>& posts) {
    std::unordered_map<std::string, std::vector<std::string>> grouped;

    for (const auto& post : posts) {
        for (const auto& tag : post.tags()) {
            grouped[tag].push_back(post.slug());
        }
    }

    return grouped;
}

std::string buildSummary(const Project& project) {
    if (project.name().empty()) {
        throw std::invalid_argument("missing project name");
    }

    std::string summary = project.name() + ":" + project.branch();
    std::ranges::transform(summary, summary.begin(), [](unsigned char ch) {
        return std::tolower(ch);
    });

    return summary;
}

std::vector<ScoreEntry> topScores(std::vector<ScoreEntry> entries) {
    std::erase_if(entries, [](const ScoreEntry& entry) {
        return entry.score() <= 0;
    });

    std::ranges::sort(entries, std::greater{}, &ScoreEntry::score);

    if (entries.size() > 5) {
        entries.resize(5);
    }

    return entries;
}

int clampScore(int score, int minimum, int maximum) {
    if (score < minimum) {
        return minimum;
    }

    if (score > maximum) {
        return maximum;
    }

    return score;
}

std::optional<ScoreEntry> pickBest(std::vector<ScoreEntry> entries) {
    if (entries.empty()) {
        return std::nullopt;
    }

    std::ranges::sort(entries, std::greater{}, &ScoreEntry::score);
    return entries.front();
}

RouteLanguage getRouteLanguage(const std::map<std::string, std::string>& search) {
    auto language = search.contains("language") ? search.at("language") : "javascript";

    if (language == "cpp") {
        return RouteLanguage::Cpp;
    }

    if (language == "python") {
        return RouteLanguage::Python;
    }

    return RouteLanguage::JavaScript;
}

std::vector<std::string> normalizeValues(std::vector<std::string> values) {
    std::erase_if(values, [](const std::string& value) {
        return value.empty();
    });

    for (auto& value : values) {
        trim(value);
    }

    return values;
}

std::optional<std::string> primaryEmail(const User& user) {
    for (const auto& method : user.contactMethods()) {
        if (method.kind() == ContactKind::Email && method.isVerified()) {
            return method.value();
        }
    }

    return std::nullopt;
}

std::string readFirstLine(const std::filesystem::path& path) {
    std::ifstream file(path);
    std::string line;

    if (!std::getline(file, line)) {
        throw std::runtime_error("empty file");
    }

    trim(line);
    return line;
}
